impl Native2dEditorState {
    pub(crate) fn handle_mcp_tool_call(
        &mut self,
        project: &ProjectRoot,
        manifest: &engine::AssetManifest,
        name: &str,
        arguments: Value,
        permissions: &AuthoringPermissions,
    ) -> Result<Value, Native2dMcpCallFailure> {
        let Some((document, operation)) = name.split_once('.') else {
            return Err(Native2dMcpCallFailure::new(
                "mcp.unknown_tool",
                format!("unknown Native 2D tool `{name}`"),
            ));
        };
        match document {
            "sprite_atlas" => handle_loaded_typed_mcp(
                self.atlas.as_mut(),
                operation,
                arguments,
                permissions,
                "Sprite Atlas",
            ),
            "sprite_animation" => handle_loaded_typed_mcp(
                self.animation.as_mut(),
                operation,
                arguments,
                permissions,
                "Sprite Animation",
            ),
            "tile_set" => handle_loaded_typed_mcp(
                self.tile_set.as_mut(),
                operation,
                arguments,
                permissions,
                "Tile Set",
            ),
            "tile_map" => {
                let loaded = self
                    .tile_map
                    .as_mut()
                    .ok_or_else(|| Native2dMcpCallFailure::no_document("Tile Map"))?;
                match operation {
                    "inspect" => {
                        require_empty_arguments(arguments)?;
                        loaded.mcp_inspect(permissions)
                    }
                    "validate" => {
                        require_empty_arguments(arguments)?;
                        loaded.mcp_validate(permissions)
                    }
                    "preview" => loaded.mcp_preview(permissions, decode_mcp(arguments)?),
                    "apply" => loaded.mcp_apply(
                        project,
                        manifest,
                        permissions,
                        decode_mcp(arguments)?,
                    ),
                    _ => Err(Native2dMcpCallFailure::new(
                        "mcp.unknown_tool",
                        format!("unknown Native 2D typed-document operation `{operation}`"),
                    )),
                }
            }
            _ => Err(Native2dMcpCallFailure::new(
                "mcp.unknown_tool",
                format!("unknown Native 2D tool `{name}`"),
            )),
        }
    }

